mapper.select:
SELECT c.*, u.name as founder_name, u.email as founder_email, cc.name as category_name FROM club c LEFT JOIN user u ON c.founder_id = u.user_id LEFT JOIN club_category cc ON c.category_id = cc.category_id
AND c.status = #{status}
AND c.category_id = #{categoryId}
AND u.email LIKE CONCAT('%', #{founderEmail}, '%')
ORDER BY c.created_at DESC

mapper.update:
UPDATE club
SET status = #{status}

    , charter = CONCAT(charter, '\n\n【审批驳回理由】：', #{rejectReason})

WHERE club_id = #{clubId}
